=== FILE: skid_buffer.v ===
`timescale 1ns / 1ps
// skid_buffer: a two-register valid/ready register slice.
//
// Implements interface_spec.md and microarchitecture.md (approved).
// - One cycle of latency, full throughput, at most two beats held.
// - s_ready, m_valid and m_data are each driven from a flop (s_ready is the
//   inverse of skid_valid); no combinational path from any input to any
//   output.
// - rst_n is active low and synchronous; it clears both valid bits. The
//   data registers are not reset (microarchitecture.md section 2).
module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    // Skid register: holds the newer of two beats while the output stalls.
    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Next-state values.
    reg             m_valid_d;
    reg [WIDTH-1:0] m_data_d;
    reg             skid_valid_d;
    reg [WIDTH-1:0] skid_data_d;

    // The output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // An upstream beat is accepted on this edge.
    wire s_fire = s_valid && !skid_valid;

    assign s_ready = !skid_valid;

    // Next state, following the table in microarchitecture.md section 3.
    always @* begin
        m_valid_d    = m_valid;
        m_data_d     = m_data;
        skid_valid_d = skid_valid;
        skid_data_d  = skid_data;
        if (m_free) begin
            if (skid_valid) begin
                // The skid beat moves to the output register; skid empties.
                m_valid_d    = 1'b1;
                m_data_d     = skid_data;
                skid_valid_d = 1'b0;
            end else begin
                // The output register loads straight from the input.
                m_valid_d = s_valid;
                m_data_d  = s_data;
            end
        end else if (s_fire) begin
            // Output stalled and a beat accepted: it goes to the skid register.
            skid_valid_d = 1'b1;
            skid_data_d  = s_data;
        end
    end

    // Control registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: no reset (their contents are don't-care while not valid).
    always @(posedge clk) begin
        m_data    <= m_data_d;
        skid_data <= skid_data_d;
    end

endmodule
=== END FILE ===
