`timescale 1ns / 1ps
// Self-checking testbench for skid_buffer, lanes at WIDTH 8 and WIDTH 1.
// Both lanes see the same handshakes; the WIDTH 1 lane carries bit 0 of the
// data. Every cycle the outputs are compared with a queue model of up to two
// beats, and every beat that leaves is compared with an in-order scoreboard.
module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg        m_ready;
    reg  [7:0] s_data8;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) u_w8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data8),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) u_w1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data8[0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    // Model state.
    reg  [1:0] cnt;
    reg  [7:0] q0;
    reg  [7:0] q1;
    reg        model_known;
    reg  [7:0] sb [0:1023];
    reg  [9:0] in_ptr;
    reg  [9:0] out_ptr;
    integer    in_count;
    integer    out_count;
    reg        hold_pending;
    reg  [7:0] hold_data;
    reg        rst_at_edge;

    integer    passed;
    integer    failed;
    integer    i;
    integer    base;
    integer    ok;
    reg [31:0] r;
    reg [8*64-1:0] nonce;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    task chk(input cond, input integer id);
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("skid_buffer_tb: check %0d failed at time %0t", id, $time);
            end
        end
    endtask

    // Outputs against the model.
    task check_outputs;
        begin
            chk(m_valid8 === (cnt != 2'd0), 1);
            chk(s_ready8 === (cnt != 2'd2), 2);
            chk(m_valid1 === (cnt != 2'd0), 3);
            chk(s_ready1 === (cnt != 2'd2), 4);
            if (cnt != 2'd0) begin
                chk(m_data8 === q0, 5);
                chk(m_data1[0] === q0[0], 6);
            end
        end
    endtask

    // Flip the inputs inside the cycle; no output may move.
    task glitch_check;
        reg       sr8;
        reg       sr1;
        reg       mv8;
        reg       mv1;
        reg [7:0] md8;
        reg       md1;
        begin
            sr8 = s_ready8;
            sr1 = s_ready1;
            mv8 = m_valid8;
            mv1 = m_valid1;
            md8 = m_data8;
            md1 = m_data1[0];
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data8 = ~s_data8;
            #1;
            if (model_known) begin
                chk(s_ready8 === sr8, 20);
                chk(s_ready1 === sr1, 21);
                chk(m_valid8 === mv8, 22);
                chk(m_valid1 === mv1, 23);
                chk(m_data8 === md8, 24);
                chk(m_data1[0] === md1, 25);
            end
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data8 = ~s_data8;
            #1;
        end
    endtask

    // One clock: check, glitch, edge, update the model and scoreboard.
    task step;
        reg       sf;
        reg       mf;
        reg [7:0] din;
        reg [7:0] dout8;
        reg       dout1;
        reg [7:0] exp_word;
        begin
            if (model_known) check_outputs;
            glitch_check;
            sf           = s_valid && (cnt != 2'd2);
            mf           = m_ready && (cnt != 2'd0);
            din          = s_data8;
            dout8        = m_data8;
            dout1        = m_data1[0];
            rst_at_edge  = !rst_n;
            hold_pending = model_known && rst_n && (cnt != 2'd0) && !m_ready;
            hold_data    = q0;
            @(posedge clk);
            #1;
            if (rst_at_edge) begin
                cnt          = 2'd0;
                model_known  = 1'b1;
                out_ptr      = in_ptr;
                out_count    = in_count;
                hold_pending = 1'b0;
            end else if (model_known) begin
                if (mf) begin
                    exp_word = sb[out_ptr];
                    chk(dout8 === exp_word, 7);
                    chk(dout1 === exp_word[0], 8);
                    out_ptr   = out_ptr + 10'd1;
                    out_count = out_count + 1;
                    q0        = q1;
                    cnt       = cnt - 2'd1;
                end
                if (sf) begin
                    sb[in_ptr] = din;
                    in_ptr     = in_ptr + 10'd1;
                    in_count   = in_count + 1;
                    if (cnt == 2'd0) q0 = din;
                    else q1 = din;
                    cnt = cnt + 2'd1;
                end
                if (hold_pending) begin
                    chk((m_valid8 === 1'b1) && (m_data8 === hold_data) &&
                        (m_valid1 === 1'b1) && (m_data1[0] === hold_data[0]), 9);
                end
                chk(out_count <= in_count, 10);
            end
        end
    endtask

    initial begin
        passed      = 0;
        failed      = 0;
        cnt         = 2'd0;
        q0          = 8'd0;
        q1          = 8'd0;
        model_known = 1'b0;
        in_ptr      = 10'd0;
        out_ptr     = 10'd0;
        in_count    = 0;
        out_count   = 0;
        hold_pending = 1'b0;
        hold_data   = 8'd0;
        rst_at_edge = 1'b0;

        // ---- Reset values ----
        rst_n   = 1'b0;
        s_valid = 1'b0;
        m_ready = 1'b0;
        s_data8 = 8'd0;
        step;
        step;
        chk((m_valid8 === 1'b0) && (s_ready8 === 1'b1) &&
            (m_valid1 === 1'b0) && (s_ready1 === 1'b1), 50);
        rst_n = 1'b1;
        step;

        // ---- One-cycle latency ----
        s_valid = 1'b1;
        s_data8 = 8'hA5;
        m_ready = 1'b1;
        chk(m_valid8 === 1'b0, 51);
        step;
        s_valid = 1'b0;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'hA5) && (m_data1[0] === 1'b1), 52);
        step;
        chk(m_valid8 === 1'b0, 53);

        // ---- Full throughput: 64 beats, one in and one out per edge ----
        base    = in_count;
        s_valid = 1'b1;
        m_ready = 1'b1;
        for (i = 0; i < 64; i = i + 1) begin
            s_data8 = i[7:0];
            chk(s_ready8 === 1'b1, 30);
            if (i > 0) chk(m_valid8 === 1'b1, 31);
            step;
            chk(out_count == in_count - 1, 34);
        end
        s_valid = 1'b0;
        step;
        step;
        chk(in_count == base + 64, 32);
        chk(out_count == in_count, 33);

        // ---- Stall with one beat held, then two ----
        base    = in_count;
        s_valid = 1'b1;
        m_ready = 1'b0;
        s_data8 = 8'h11;
        step;
        chk((m_valid8 === 1'b1) && (s_ready8 === 1'b1), 13);  // second must be accepted
        s_data8 = 8'h22;
        step;
        chk((s_ready8 === 1'b0) && (m_data8 === 8'h11), 14);
        s_data8 = 8'h33;
        step;                                                // third must not be accepted
        chk((s_ready8 === 1'b0) && (m_data8 === 8'h11) && (cnt == 2'd2), 15);
        chk(in_count == base + 2, 16);
        // ---- Ready rises after the stall ----
        m_ready = 1'b1;
        step;
        chk((s_ready8 === 1'b1) && (m_data8 === 8'h22), 17);
        step;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'h33), 18);
        s_valid = 1'b0;
        step;
        chk((m_valid8 === 1'b0) && (out_count == in_count) && (in_count == base + 3), 19);

        // ---- Random traffic against the model, with a reset mid-run ----
        for (i = 0; i < 3000; i = i + 1) begin
            r       = $random;
            rst_n   = (i != 1500);
            s_valid = (r[1:0] != 2'b00);
            s_data8 = r[15:8];
            if (i < 1000)      m_ready = r[2];
            else if (i < 2000) m_ready = (r[4:2] != 3'b000);
            else               m_ready = (r[4:2] == 3'b000);
            step;
        end
        rst_n   = 1'b1;
        s_valid = 1'b0;
        m_ready = 1'b1;
        step;
        step;
        step;
        chk((cnt == 2'd0) && (m_valid8 === 1'b0) && (m_valid1 === 1'b0) &&
            (out_count == in_count), 40);

        // ---- Reset with two beats held ----
        s_valid = 1'b1;
        m_ready = 1'b0;
        s_data8 = 8'hC3;
        step;
        s_data8 = 8'h3C;
        step;
        chk((cnt == 2'd2) && (s_ready8 === 1'b0) && (s_ready1 === 1'b0), 41);
        rst_n = 1'b0;
        step;
        rst_n   = 1'b1;
        s_valid = 1'b0;
        chk((m_valid8 === 1'b0) && (s_ready8 === 1'b1) &&
            (m_valid1 === 1'b0) && (s_ready1 === 1'b1), 42);
        s_valid = 1'b1;
        s_data8 = 8'h5A;
        m_ready = 1'b1;
        step;
        s_valid = 1'b0;
        chk((m_valid8 === 1'b1) && (m_data8 === 8'h5A), 44);
        step;
        chk((m_valid8 === 1'b0) && (out_count == in_count), 43);

        // ---- Verdict ----
        ok = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (ok == 0) nonce = {(8*64){1'b0}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
